from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class CpIfInterface(SchemaObject):
    link_type = SchemaField(name='link_type', not_null=True)
    link_status = SchemaField(name='link_status', not_null=True)
    local_ip_address = SchemaField(name='local_ip_address', optional=True)
    remote_ip_address = SchemaField(name='remote_ip_address', optional=True)
    peer_ne = SchemaField(name='peer_ne', optional=True)

    def __init__(self, link_type, link_status, local_ip_address, remote_ip_address, peer_ne):
        self.link_type = link_type
        self.link_status = link_status
        self.local_ip_address = local_ip_address
        self.remote_ip_address = remote_ip_address
        self.peer_ne = peer_ne

        super(CpIfInterface, self).__init__()


class GetVNFCSASMV1(SchemaObject):
    alarms = SchemaField(name="alarms")
    availability_status = SchemaField(name="availabilityStatus")
    dist_names = SchemaField(name="distNames")
    hostname = SchemaField(name="hostname")
    id = SchemaField(name="id", not_null=True)
    instance = SchemaField(name="instance", not_null=True)
    ip_interfaces = SchemaField(name="ip_interfaces")
    name = SchemaField(name="name")
    operational_state = SchemaField(name="operationalState")
    role = SchemaField(name="role")
    software_version = SchemaField(name="softwareVersion")
    links = SchemaField(name='links', optional=True, many=True, klass=CpIfInterface)

    def __init__(self, alarms, availability_status, dist_names, hostname, id, instance, ip_interfaces, name,
                 operational_state, role, software_version, links):
        self.alarms = alarms
        self.availability_status = availability_status
        self.dist_names = dist_names
        self.hostname = hostname
        self.id = id
        self.instance = instance
        self.ip_interfaces = ip_interfaces
        self.name = name
        self.operational_state = operational_state
        self.role = role
        self.software_version = software_version
        self.links = links
        super(GetVNFCSASMV1, self).__init__()
